    private static final Map<String, Entrada> BY_CODIGO =
            ENTRADAS.stream().collect(Collectors.toUnmodifiableMap(Entrada::codigo, Function.identity()));

    private MatrizErrores() {}

    /**
     * Returns every row, in matrix order.
     *
     * @return the rows
     */
    public static List<Entrada> entradas() {
        return ENTRADAS;
    }

    /**
     * Returns the row of a code.
     *
     * @param codigo the code
     * @return the row, if the code is in the matrix
     */
    public static Optional<Entrada> of(String codigo) {
        return Optional.ofNullable(BY_CODIGO.get(codigo));
    }
